// subsets with a loop; with duplicates in the input — after Array.Sort(nums)
void Dfs(int start) {
    res.Add(new List<int>(path));                    // every node is an answer
    for (int i = start; i < nums.Length; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;  // duplicate on this level
        path.Add(nums[i]);
        Dfs(i + 1);                                  // further — only to the right of i
        path.RemoveAt(path.Count - 1);
    }
}
